Q: Why can't I store the array of objects in a State: React JS
A: <p>Because setState is asynchronous. You need to console log your state value outside of the useEffect, like this,</p>
<pre><code>import Axios from 'axios'
import { useEffect,useState } from 'react'

const Favourite=()=&gt; {
const [favcoin,setFavcoin]=useState([])

//Getting all the favorites

  useEffect(() =&gt; {
    Axios.post('http://localhost:9000/getFav',
    { userid : localStorage.getItem('userid') }
      ).then(
        (response)=&gt;{
          setFavcoin(response.data)
       }
    )
  }, []);

console.log(favcoin);

return (
    &lt;span&gt;{JSON.stringify(favcoin)}&lt;/span&gt;
)
}
</code></pre>
<p>export default Favourite;</p>

